describe('Recently Searched Terms Suggestions', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should display recently searched terms as suggestions in search box', () => {
    // Perform first search
    cy.get('[data-testid="search-input"]').type('cypress testing');
    cy.get('[data-testid="search-button"]').click();
    cy.url().should('include', 'q=cypress+testing');

    // Return to home and open search
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').click();

    // Verify recently searched term appears in suggestions
    cy.get('[data-testid="search-suggestions"]').should('be.visible');
    cy.get('[data-testid="search-suggestions"]').should('contain', 'cypress testing');
  });

  it('should display multiple recently searched terms in correct order', () => {
    // Perform multiple searches
    cy.get('[data-testid="search-input"]').type('automation');
    cy.get('[data-testid="search-button"]').click();
    cy.wait(500);

    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').type('qa testing');
    cy.get('[data-testid="search-button"]').click();
    cy.wait(500);

    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').type('javascript');
    cy.get('[data-testid="search-button"]').click();
    cy.wait(500);

    // Return and check suggestions appear in reverse chronological order
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').click();

    cy.get('[data-testid="search-suggestions"]').should('be.visible');
    cy.get('[data-testid="search-suggestions"] li').eq(0).should('contain', 'javascript');
    cy.get('[data-testid="search-suggestions"] li').eq(1).should('contain', 'qa testing');
    cy.get('[data-testid="search-suggestions"] li').eq(2).should('contain', 'automation');
  });

  it('should not display suggestions when search input is empty and unfocused', () => {
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-suggestions"]').should('not.exist');
  });

  it('should allow selecting a suggestion and performing search', () => {
    // Perform initial search
    cy.get('[data-testid="search-input"]').type('test search');
    cy.get('[data-testid="search-button"]').click();

    // Return and select from suggestions
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-suggestions"]').should('be.visible');
    cy.get('[data-testid="search-suggestions"] li').first().click();

    // Verify search was performed with selected term
    cy.url().should('include', 'q=test+search');
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle special characters in recently searched terms', () => {
    // Search with special characters
    cy.get('[data-testid="search-input"]').type('C++ & C#');
    cy.get('[data-testid="search-button"]').click();
    cy.wait(500);

    // Verify suggestion appears correctly
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-suggestions"]').should('contain', 'C++ & C#');
  });

  it('should clear recently searched terms when local storage is cleared', () => {
    // Perform search
    cy.get('[data-testid="search-input"]').type('to be cleared');
    cy.get('[data-testid="search-button"]').click();

    // Clear storage
    cy.clearLocalStorage();
    cy.visit('http://localhost:3000');

    // Verify no suggestions appear
    cy.get('[data-testid="search-input"]').click();
    cy.get('[data-testid="search-suggestions"]').should('not.exist');
  });
});
